import re

def parse_duration(s: str) -> int:
    """Convert a human duration string into whole seconds."""
    s = s.strip()
    if not s:
        raise ValueError("empty string")

    # Try colon form: mm:ss or hh:mm:ss (integer parts only)
    if re.fullmatch(r'\d+:\d+(:\d+)?', s):
        parts = s.split(':')
        if len(parts) == 2:
            # mm:ss
            minutes = int(parts[0])
            seconds = int(parts[1])
            return minutes * 60 + seconds
        elif len(parts) == 3:
            # hh:mm:ss
            hours = int(parts[0])
            minutes = int(parts[1])
            seconds = int(parts[2])
            return hours * 3600 + minutes * 60 + seconds
        else:
            raise ValueError("invalid colon form")

    # Try bare number (integer or decimal)
    if re.fullmatch(r'\d+(\.\d+)?', s):
        return int(float(s))

    # Try unit-based forms: combinations of number+unit, possibly with fractions
    # Pattern: optional digits, optional decimal point and digits, then a unit letter (s, m, h)
    # Multiple such groups concatenated, largest to smallest
    pattern = r'(\d+(?:\.\d+)?)\s*([smhSMH])'
    matches = re.findall(pattern, s)

    if not matches:
        raise ValueError(f"invalid duration: {s!r}")

    # Reconstruct what was matched to ensure the whole string is consumed
    reconstructed = ''
    for num_str, unit in matches:
        reconstructed += num_str + unit

    # Remove whitespace from original for comparison
    s_no_space = re.sub(r'\s+', '', s)
    if reconstructed.lower() != s_no_space.lower():
        raise ValueError(f"invalid duration: {s!r}")

    # Validate order: units must be from largest to smallest (h, m, s)
    unit_order = {'h': 0, 'm': 1, 's': 2}
    prev_order = -1
    for _, unit in matches:
        u = unit.lower()
        order = unit_order[u]
        if order <= prev_order:
            raise ValueError(f"invalid duration: {s!r}")
        prev_order = order

    total_seconds = 0.0
    for num_str, unit in matches:
        value = float(num_str)
        u = unit.lower()
        if u == 'h':
            total_seconds += value * 3600
        elif u == 'm':
            total_seconds += value * 60
        elif u == 's':
            total_seconds += value

    return int(total_seconds)

